// Hand-written. Not generated by Speakeasy.
//
// Keeps an error response's body readable after the SDK has thrown it away.
//
// Deciding that a resource is gone is judged from the body, not the status
// code (see missing_service.go). The generated SDK defeats that on the paths
// that matter most: on a 404 it calls utils.DrainBody, which reads the body to
// discard and replaces it with an empty reader.
//
//	internal/sdk/service.go           service Remove
//	internal/sdk/clientmanagement.go  client Delete
//
// So Delete saw an empty body for every 404, serviceIsGone and clientIsGone
// both answered false, and a resource genuinely deleted in the console made
// "destroy -refresh=false" fail. Refresh normally hides that, which is why it
// took a reviewer going at the Delete path directly to find it.
//
// The fix is a transport rather than more patch sites in generated files. A
// transport is a file the generator never writes, it covers every operation at
// once including ones added later, and it cannot be defeated by the SDK
// because it has already run by the time the SDK looks at the response.
//
// Only responses that failed are captured, and only up to a limit. A success
// body can be large and is read by the SDK anyway; an error body is small and
// is the only one anything here needs to read twice.
package provider

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
)

// noteKey retrieves the note attached to a request. A context value rather
// than a response header: a header would be printed by every diagnostic that
// dumps the response, which is most of them, and the capture duplicates the
// body that the dump already shows.
type noteKey struct{}

// note travels with the request and is filled in once the response is in
// hand. The transport attaches it, so anything later holding the response can
// reach it through res.Request.
type note struct {
	// body is what the response said, kept because the SDK calls DrainBody on
	// a 404 and that is the Delete path.
	body []byte

	// where is the place this resource lives, as configured, not whichever
	// host answered. Creating or deleting a service goes to the IdP, so the
	// answering host there is login.authlete.com or the customer's own
	// identity server, while the service lives on server_url. Recording the
	// answering host on Create was the first version of this, and it turned
	// every genuine deletion into a reported move.
	where Location
}

// Location is everything that decides which objects a request can see. The
// cluster alone is not enough: deleting a service goes through the IdP, which
// looks the service up under an organization on an api server, and answers
// "Service is not found" when any of those three is wrong. A destroy run with
// the wrong organization_id therefore reported success and deleted nothing,
// which is the same orphaning the cluster check exists to prevent.
type Location struct {
	Host    string `json:"host"`
	IdpHost string `json:"idp_host,omitempty"`
	Org     int64  `json:"organization_id,omitempty"`
	API     int64  `json:"api_server_id,omitempty"`
}

// Describe renders a location for a diagnostic, naming only what is set.
func (l Location) Describe() string {
	out := l.Host
	if out == "" {
		out = "an unknown host"
	}
	var extra []string
	if l.IdpHost != "" {
		extra = append(extra, "identity server "+l.IdpHost)
	}
	if l.Org != 0 {
		extra = append(extra, fmt.Sprintf("organization %d", l.Org))
	}
	if l.API != 0 {
		extra = append(extra, fmt.Sprintf("api server %d", l.API))
	}
	if len(extra) > 0 {
		out += " (" + strings.Join(extra, ", ") + ")"
	}
	return out
}

// Differences names the parts that changed, for a message that says what to
// put back rather than only that something moved.
func (l Location) Differences(other Location) []string {
	var out []string
	for _, c := range []struct {
		name string
		a, b string
	}{
		{"server_url", l.Host, other.Host},
		{"idp_host", l.IdpHost, other.IdpHost},
		{"organization_id", fmt.Sprint(l.Org), fmt.Sprint(other.Org)},
		{"api_server_id", fmt.Sprint(l.API), fmt.Sprint(other.API)},
	} {
		if c.a != c.b {
			out = append(out, c.name)
		}
	}
	return out
}

// maxCapturedBody bounds what is held in memory. Authlete's error bodies are a
// few hundred bytes; an HTML error page from a proxy is a few kilobytes. A
// body larger than this is not one of the markers being looked for.
const maxCapturedBody = 1 << 20

// bodyCapturingTransport records the body of any response that failed, so a
// later reader still has it after the SDK drains it.
type bodyCapturingTransport struct {
	where Location
	next  http.RoundTripper
}

// NewBodyCapturingTransport wraps next. It belongs outermost in the chain, as
// the transport the SDK itself calls, so that it is the last to see a response
// before the SDK does.
func NewBodyCapturingTransport(serverURL, idpHost string, organizationID, apiServerID int64, next http.RoundTripper) http.RoundTripper {
	if next == nil {
		next = http.DefaultTransport
	}
	host := ""
	if u, err := url.Parse(strings.TrimSpace(serverURL)); err == nil {
		host = u.Host
	}
	return &bodyCapturingTransport{
		where: Location{
			Host:    host,
			IdpHost: strings.TrimSpace(idpHost),
			Org:     organizationID,
			API:     apiServerID,
		},
		next: next,
	}
}

func (t *bodyCapturingTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	// RoundTrip must not modify the request it is given, so the note is
	// attached to a clone. res.Request is that clone, which is how anything
	// holding the response reaches the note.
	n := &note{where: t.where}
	outgoing := req.Clone(context.WithValue(req.Context(), noteKey{}, n))

	res, err := t.next.RoundTrip(outgoing)
	if err != nil || res == nil {
		return res, err
	}
	// 2xx and 3xx are the paths the SDK reads properly, and a success body can
	// be megabytes. Nothing here needs them.
	if res.StatusCode < 400 || res.Body == nil {
		return res, nil
	}

	raw, readErr := io.ReadAll(io.LimitReader(res.Body, maxCapturedBody))
	res.Body.Close()
	// Put back what was read either way, so the SDK sees the response it would
	// have seen. A failure to read is not reported: it costs the body-based
	// check, which then falls back to reporting the response rather than
	// acting on it, and that is the safe direction.
	res.Body = io.NopCloser(bytes.NewReader(raw))
	if readErr != nil || len(raw) == 0 {
		return res, nil
	}

	n.body = raw
	return res, nil
}

// noteOn returns the note the transport attached to this response's request,
// or nil for a response it never saw.
func noteOn(res *http.Response) *note {
	if res == nil || res.Request == nil {
		return nil
	}
	n, _ := res.Request.Context().Value(noteKey{}).(*note)
	return n
}

// capturedBody returns the body recorded for a failed response, or nil if
// there is none: a successful response, a response this transport never saw,
// or one whose body could not be read.
func capturedBody(res *http.Response) []byte {
	if n := noteOn(res); n != nil {
		return n.body
	}
	return nil
}

// locationOf returns where the resource this response is about lives, as
// configured. It falls back to the host that answered, for a response this
// transport never saw.
func locationOf(res *http.Response) Location {
	if n := noteOn(res); n != nil && n.where.Host != "" {
		return n.where
	}
	if res == nil || res.Request == nil || res.Request.URL == nil {
		return Location{}
	}
	return Location{Host: res.Request.URL.Host}
}
